import type { AxisSortableData } from '@components/app-wrapper/drag-and-drop-provider/types'
import type { DraggableSyntheticListeners } from '@dnd-kit/core'
import { useSortable } from '@dnd-kit/sortable'
import { CSS } from '@dnd-kit/utilities'
import { isValidCellValueDimension } from '@modules/dimension/cell-value'
import type { Axis } from '@types'
import { useMemo, type CSSProperties } from 'react'
import type { LayoutDimension } from './chip'
import type { ChipBaseProps } from './chip-base'

type UseChipDndArgs = {
    dimension: LayoutDimension
    axisId: Axis
    chipBaseProps: ChipBaseProps
    insertAfter: boolean
}

type UseChipDndReturn = {
    sortable: ReturnType<typeof useSortable>
    setNodeRef: (node: HTMLElement | null) => void
    attributes: ReturnType<typeof useSortable>['attributes']
    listeners: DraggableSyntheticListeners
    isOver: boolean
    isDragging: boolean
    style: CSSProperties | undefined
}

export const useChipDnd = ({
    dimension,
    axisId,
    chipBaseProps,
    insertAfter,
}: UseChipDndArgs): UseChipDndReturn => {
    const droppableData = useMemo<AxisSortableData>(
        () => ({
            dimensionId: dimension.id,
            axis: axisId,
            overlayItemProps: chipBaseProps,
            insertAfter,
            isLayoutBlocked: false,
            canBeCellValue: isValidCellValueDimension(dimension),
        }),
        [axisId, dimension, chipBaseProps, insertAfter]
    )

    const sortable = useSortable({
        id: dimension.id,
        data: droppableData,
    })

    const {
        attributes,
        isDragging,
        isOver,
        isSorting,
        listeners,
        setNodeRef,
        transform,
        transition,
    } = sortable

    const style = useMemo<CSSProperties | undefined>(
        () =>
            transform
                ? {
                      transform: isSorting
                          ? undefined
                          : CSS.Translate.toString({
                                x: transform.x,
                                y: transform.y,
                                scaleX: 1,
                                scaleY: 1,
                            }),
                      transition,
                  }
                : undefined,
        [transform, isSorting, transition]
    )

    return {
        sortable,
        setNodeRef,
        attributes,
        listeners,
        isOver,
        isDragging,
        style,
    }
}
